(X_1 \subset X_1')
}
}
\quad
\begin{matrix}
\text{and a commutative} \\
\text{diagram of schemes}
\end{matrix}
\quad
\vcenter{
\xymatrix{
X_2' \ar[r] \ar[d] & S_2 \ar[d] \\
X_1' \ar[r] & S_1
}
}
$$
with $X_2 \to X_1$ and $S_2 \to S_1$ \'etale.
